    public static void testEveryLineOfNormalizationTestTxt() {
        byte[] f = emon.Testport.testFile("normalize/NormalizationTest.txt");
        emon.Port.Cells c1 = emon.Port.newCells();
        emon.Port.Cells c2 = emon.Port.newCells();
        emon.Port.Cells c3 = emon.Port.newCells();
        emon.Port.Cells c4 = emon.Port.newCells();
        emon.Port.Cells c5 = emon.Port.newCells();
        emon.Port.Cells c2b = emon.Port.newCells();
        emon.Port.Cells c3b = emon.Port.newCells();
        emon.Port.Cells c4b = emon.Port.newCells();
        emon.Port.Cells c5b = emon.Port.newCells();
        emon.Port.Cells out = emon.Port.newCells();
        emon.Port.Cells tmp = emon.Port.newCells();
        int n = emon.Port.blobLen(f);
        int pos = 0;
        int line = 0;
        int rows = 0;
        int e = 0;
        int s1 = 0;
        int s2 = 0;
        int s3 = 0;
        int s4 = 0;
        int s5 = 0;
        int bad = 0;
        while (pos < n) {
            line += 1;
            e = ntNl(f, pos);
            // Skip blank lines, `#` comments and `@Part` headings.
            if ((pos < e) && (emon.Port.blobU8(f, pos) != 35) && (emon.Port.blobU8(f, pos) != 64)) {
                rows += 1;
                s1 = ntSemi(f, pos, e);
                s2 = ntSemi(f, s1 + 1, e);
                s3 = ntSemi(f, s2 + 1, e);
                s4 = ntSemi(f, s3 + 1, e);
                s5 = ntSemi(f, s4 + 1, e);
                ntCps(f, pos, s1, c1);
                ntCps(f, s1 + 1, s2, c2);
                ntCps(f, s2 + 1, s3, c3);
                ntCps(f, s3 + 1, s4, c4);
                ntCps(f, s4 + 1, s5, c5);
                // Rust takes every `Cells` as `&mut`, so one can not be passed
                // twice in a call: the pairs that compare a column with itself
                // get a second copy.
                ntCps(f, s1 + 1, s2, c2b);
                ntCps(f, s2 + 1, s3, c3b);
                ntCps(f, s3 + 1, s4, c4b);
                ntCps(f, s4 + 1, s5, c5b);
                bad = 0;
                if (ntNfcIs(c1, c2, out, tmp) == 0) {
                    bad += 1;
                }
                if (ntNfcIs(c2, c2b, out, tmp) == 0) {
                    bad += 2;
                }
                if (ntNfcIs(c3, c2, out, tmp) == 0) {
                    bad += 4;
                }
                if (ntNfcIs(c4, c4b, out, tmp) == 0) {
                    bad += 8;
                }
                if (ntNfcIs(c5, c4, out, tmp) == 0) {
                    bad += 16;
                }
                if (ntNfdIs(c1, c3, out) == 0) {
                    bad += 32;
                }
                if (ntNfdIs(c2, c3, out) == 0) {
                    bad += 64;
                }
                if (ntNfdIs(c3, c3b, out) == 0) {
                    bad += 128;
                }
                if (ntNfdIs(c4, c5, out) == 0) {
                    bad += 256;
                }
                if (ntNfdIs(c5, c5b, out) == 0) {
                    bad += 512;
                }
                emon.Testport.assertEqAt(bad, 0, "failed checks (bitmask)", line);
            }
            pos = e + 1;
        }
        emon.Testport.assertEq(rows, 20171, "the corpus has this many test lines");
    }
