    public static void testMarksArePutInCanonicalOrderBeforeComposing() {
        // q, dot above (230), dot below (220): no precomposed form, so the
        // marks only REORDER, dot below first. With an `a` the dot below
        // then composes (U+1EA1) and the dot above is left over.
        emon.Port.Cells src = emon.Port.newCells();
        emon.Port.Cells want = emon.Port.newCells();
        emon.Port.Cells out = emon.Port.newCells();
        emon.Port.Cells tmp = emon.Port.newCells();
        ntLit(emon.Testport.textBlob("0071 0307 0323"), src);
        ntLit(emon.Testport.textBlob("0071 0323 0307"), want);
        emon.Testport.assertEq(ntNfcIs(src, want, out, tmp), 1, "q dot-above dot-below -> q dot-below dot-above");
        ntLit(emon.Testport.textBlob("0061 0307 0323"), src);
        ntLit(emon.Testport.textBlob("1EA1 0307"), want);
        emon.Testport.assertEq(ntNfcIs(src, want, out, tmp), 1, "a dot-above dot-below -> U+1EA1 dot-above");
    }
